using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class ProbeResolverCoverageTests
{
    private const string ExcludeAttribute = "[global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]";

    private const string TestSource = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver]
            partial class GeneratedMessagePackResolver
            {
            }
        }
        """;

    [Fact]
    public async Task EveryTypeInResolverFileIsDecorated()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "ProbeResolverCoverageTests",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);
        GeneratorDriverRunResult result = driver.GetRunResult();

        var resolverTree = result.GeneratedTrees.FirstOrDefault(t => t.FilePath.Contains("GeneratedMessagePackResolver") && !t.FilePath.Contains("MyObject"));
        Assert.NotNull(resolverTree);
        string text = resolverTree!.GetText().ToString().Replace("\r\n", "\n");

        // Find each generated class/struct declaration and require the attribute (with optional guard) directly before it,
        // accounting for modifiers and generic clauses.
        var missing = new List<string>();
        var lines = text.Split('\n');
        for (int i = 0; i < lines.Length; i++)
        {
            string trimmed = lines[i].TrimStart();
            if (trimmed.StartsWith("class ") || trimmed.StartsWith("partial class ") ||
                trimmed.StartsWith("static class ") || trimmed.StartsWith("private static class ") ||
                trimmed.StartsWith("internal sealed class ") || trimmed.StartsWith("sealed class ") ||
                trimmed.StartsWith("public class ") || trimmed.StartsWith("internal class "))
            {
                // Look backwards past attributes/whitespace for the ExcludeFromCodeCoverage attribute near this line.
                bool found = false;
                for (int j = i - 1; j >= 0 && j >= i - 4; j--)
                {
                    string prev = lines[j];
                    if (prev.Contains("ExcludeFromCodeCoverage"))
                    {
                        found = true;
                        break;
                    }
                    if (prev.Trim() == "#endif" || prev.Trim() == "#if !NETSTANDARD2_0 && !NETFRAMEWORK" || prev.Trim().Length == 0)
                    {
                        continue;
                    }
                    break;
                }

                if (!found)
                {
                    missing.Add(trimmed);
                }
            }
        }

        Assert.True(missing.Count == 0, "Generated types lacking ExcludeFromCodeCoverage:\n" + string.Join("\n", missing));
    }
}

using System.Collections.Generic;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class ProbeGuardCompileTests
{
    private const string TestSource = """
        using MessagePack;

        [MessagePackObject]
        public class MyObject
        {
            [Key(0)]
            public int Value { get; set; }
        }

        namespace MessagePack
        {
            [GeneratedMessagePackResolver]
            partial class GeneratedMessagePackResolver
            {
            }
        }
        """;

    [Fact]
    public async Task GeneratedCodeCompilesWhenAttributeUnavailable()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "ProbeGuardCompileTests",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out var updatedCompilation, out _);
        GeneratorDriverRunResult result = driver.GetRunResult();

        // Re-parse the generated trees with NETSTANDARD2_0 and NETFRAMEWORK defined, simulating a target where
        // System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage is absent. Then confirm the attribute reference is gone.
        var options = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: new[] { "NETSTANDARD2_0", "NETFRAMEWORK" });
        var trees = result.GeneratedTrees
            .Select(t => CSharpSyntaxTree.ParseText(t.GetText().ToString(), options, path: t.FilePath))
            .ToArray();

        // With the guard active and the symbol defined, the attribute line must be excluded. If the emit code
        // left the attribute outside the #if, it will remain in the text after preprocessing.
        foreach (var tree in trees)
        {
            var disabled = tree.GetRoot().DescendantNodes(descendIntoTrivia: true)
                .OfType<Microsoft.CodeAnalysis.CSharp.Syntax.AttributeSyntax>()
                .Select(a => a.ToString())
                .Where(s => s.Contains("ExcludeFromCodeCoverage"))
                .ToList();
            Assert.True(disabled.Count == 0, $"Attribute not guarded out under NETSTANDARD2_0/NETFRAMEWORK in {tree.FilePath}:\n{string.Join("\n", disabled)}");
        }
    }
}

using System.Collections.Immutable;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;
using Xunit;

public class ProbeNestedConstraintTests
{
    private const string TestSource = """
        using MessagePack;

        public class Container<T> where T : class
        {
            [MessagePackObject]
            public class Nested
            {
                [Key(0)]
                public int Value { get; set; }
            }
        }
        """;

    [Fact]
    public async Task NestedFormatterWithOuterConstraintParsesCleanly()
    {
        ImmutableArray<MetadataReference> frameworkReferences = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);

        CSharpCompilation compilation = CSharpCompilation.Create(
            assemblyName: "ProbeNestedConstraintTests",
            syntaxTrees: [CSharpSyntaxTree.ParseText(TestSource, new CSharpParseOptions(LanguageVersion.Latest))],
            references: frameworkReferences.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePack)),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = (CSharpGeneratorDriver)driver.RunGeneratorsAndUpdateCompilation(compilation, out var updatedCompilation, out var generatorDiagnostics);
        GeneratorDriverRunResult result = driver.GetRunResult();

        Assert.Empty(generatorDiagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.True(result.GeneratedTrees.Length > 0, "Generator produced no output.");

        var formatterTree = result.GeneratedTrees.FirstOrDefault(t => t.FilePath.Contains("Container"));
        Assert.True(formatterTree != null, "No generated tree for Container. Trees: " + string.Join(", ", result.GeneratedTrees.Select(t => t.FilePath)));
        var syntaxRoot = formatterTree!.GetRoot();
        Assert.True(syntaxRoot != null, "Generated tree has no root.");

        // The generated source must parse without syntax errors. A misplaced brace from the
        // anyConstraints branch would surface as a syntax diagnostic here.
        var syntaxErrors = syntaxRoot!.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        Assert.True(syntaxErrors.Count == 0, "Generated source has syntax errors: " + string.Join("; ", syntaxErrors) + "\n" + formatterTree.GetText().ToString());

        Assert.Empty(updatedCompilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
    }
}
